import{_ as t,c as s,o as i,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"周易經傳集解卷十","description":"周易經傳集解 - 周易經傳集解卷十","frontmatter":{"title":"周易經傳集解卷十","description":"周易經傳集解 - 周易經傳集解卷十"},"headers":[],"relativePath":"classics/jingchuan-jijie/011.md","filePath":"classics/jingchuan-jijie/011.md"}'),r={name:"classics/jingchuan-jijie/011.md"};function c(o,a,l,d,p,j){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"周易經傳集解卷十",tabindex:"-1"},[n("周易經傳集解卷十 "),e("a",{class:"header-anchor",href:"#周易經傳集解卷十","aria-label":"Permalink to “周易經傳集解卷十”"},"​")],-1),e("p",null,"欽定四庫全書周易經傳集解臨觀卷十 ​宋林栗撰。序卦曰：「蠱者，事也。有事而後可大，故受之以臨。臨者，大也。」「臨」之成卦，「蠱」之變也。自「蠱」之「臨」，「巽」變為「兌」，「艮」變為「坤」，二、五不動而成也。「巽」變者「兌」，入而說也；「艮」變為「坤」，止而順也。入而不說，則事不可成；止而不順，則功不可就。此「蠱」之所以為事，而「臨」之所以為「大」也。「蠱」之二、五，其體「艮」「兌」，有相與之意焉，事之所為作也。然而六五幹父而有用譽之嫌，九二幹母而有不可貞之疑。所以然者，以上有九在上故也。及其在「臨」，則六五為「坤」，而九二為「震」。「坤」，母也；「震」，長子也。然後名正而言順，事立而功成矣，是以謂之「臨」也。「臨之為大，何也？」曰：所以為臨者，澤上有地也。澤大矣，而地臨之，澤不逾地，地斯為大矣。君子之臨民，如地之臨澤可也。若以山而臨之，斯損而已矣。或曰：「陽為大，而大稱之，何也？」曰：固哉！子之為易也。博厚如地，而猶不可以稱大乎？對乾而言，斯有所避焉耳。乾稱大，則坤稱至，乾稱久，則坤稱大也。書曰：「臨下以簡。」仲弓曰：「居敬而行簡，以臨其民。」子曰：「乾以易知，坤以簡能。易則易知，簡則易從。」易知則有親，易從則有功。有親則可久，有功則可大。茲「坤」、「兌」之所以為「臨」歟？臨：元亨，利貞，至於八月有兇。彖曰：剛浸而長，說而順，剛中而應，大亨以正，天之道也。至於「八月有兇」，消不久也。下兌上坤，成卦曰「臨」者，初為兌，二為震，三四為坤。兌為澤，坤為地，震為動。澤不動而地臨之，固其常矣。及其動也，有至於「懷山襄陵」，則「坤」之所不能「臨」也。今兌、震二陽，不越乎中，而地臨其上，此其所以為「臨」歟？故象不言地中有澤，而言澤上有地，謂之浸長而不能逾於地也。故曰：「剛浸而長，說而順，剛中而應，是以謂之臨也。」「臨，元亨利貞，至於八月有㓙」，何謂也？曰：「臨」之成卦，反覆初象。初兌二震，則三、四為坤；三巽四艮，則五、上為坤。震、兌、艮、巽者，隨之所謂「元亨利貞」也。四象皆坤者，坤之所謂「元亨利貞」也。今「臨」之象體，配天之德，而應四時之序，是以稱之也。然則觀之不為「元亨利貞」，何也？曰：「臨」、觀之義，或與或求。與者在此，求者在彼。既已言之於「臨」，雖不言於「觀」可矣。「臨」之事象，既應四時之序，而觀之有孚，夫子釋之以「四時不忒」，亦可以知其指歸矣。故子曰：「大亨以正，天之道也」。「至於八月有兇」者，二陽為「臨」，二陰為「遁」。聖人貴陽而賤陰，好治而惡亂，方長而慮其消，方吉而示之兇也。然自「臨」至「遁」，才七月耳，而謂之「八月」者，自「復」數之也。陰陽之消長，必自其始而推之。日陽物，月陰物，七陽數，八陰數，主陽而言，故稱曰「八」。「臨」之彖曰「八月有兇」是也。自「復」至「遁」凡八卦，自一陽之生至二陰之長，八月也。聖人之意若曰君子小人相為消長，如晝夜寒暑之常。今「臨」之時，二陽乃長，至於八月，有兇道焉，不可不預為之戒也。故曰「至於八月有兇，消不久也」。王氏曰：有兇者，不必㓙，不必無兇也，善求之而已矣。陽生於子而終於巳，陰生於午而終於亥，此周人之正，先王所以稽天統也。陽起於寅而終於未，陰起於申而終於醜，此夏后氏之正，先王所以授人時也。梓慎有言「夏數得天」，孔子亦曰：「行夏之時」。聖人於此，未嘗偏廢焉。非期不廢，不可廢也。然在天之運，杪忽而難窺；在人之時，有象而可證。易之為書，以象示人者也。故愚於夏時，每有考焉。先儒以「乾」、坤十二爻，「復」、姤十二卦，分配十二月，建子之月為「復」，為初九；建醜之月為「臨」，為九二。愚於乾、坤二卦，既辨爻配之非，至於此卦，則配復之象曰：「先王以至日閉關，摘旅不行，後不省方。」「臨」之彖曰：「至於八月有兇。」說者曰：「至日者，冬至之日也。八月者，夏之六月，周之八月也。」其餘十卦，雖無其義，固可以數推矣。然十月乾亥而謂之「坤」，正月勾萌而謂之「泰」，二月陽微而謂之「壯」，諸如此類，義所未安。按春秋書：「春王正月，冬十有二月。」詩云：「四月維夏，六月徂暑，七月流火，九月授衣。」皆以夏時為正也。竊謂四時之序，十二月之名，冬不可以為春，夏不可以為秋，所謂三代不相沿襲者，但以十一月、十二月為歲首。再太甲惟元祀十有二月乙丑，武王十有一年一月戊午，秦漢元年冬十月，是其例也。唐虞巡狩，十一月方如北嶽，而謂「後不省方」，何哉？復為十一月，臨為十二月，「八月有兇」，當是建酉。酉者，兌也。兌為小人，故彖言「有兇」，而仲尼有「消不久」之辭。「摘旅不行，後不省方」，施之正月，義或然矣。易之作也，其在商之未亡，而已用周正，亦恐不然。或曰：「既稱至日，便是冬至之日，夫復何疑？」曰：「理之所在，不以文辭。若以至日便為冬至，惡知其不為夏至乎？」如孟子言「至於日至之時皆熟焉」，又當為何至也？然則「臨」之八月，是為夏正，學者訂之。象曰：澤上有地，「臨」。君子以教思無窮，容保民無疆。「澤」者，「兌」也。「地」者，「坤」也。「澤上有地」，「臨」之象也。宋氏曰：以土製水，宜若易者。然迫之以險隘，奔潰四出，壞之而後已。居之以寬大，則蓄而為澤矣。君子之於民亦然。扼之以勢，勢則有盡；親之以教，教則無窮。是以忘有盡之勢，思無窮之教，以保無疆之民，是以謂之「臨」也。雜卦曰：「臨觀之義，或與或求。」「與」者，臨也；求者，觀也。「臨」者，以「坤」臨「兌」也；「觀」者，以「坤」觀「震」也。二陽在下，上以「鹹臨」，與之之義也；二陽在上，下觀而化，求之之義也。有感而後有應，有施而後有求。我無以與之，彼曷為求我哉？是以「臨」之六爻，皆有與下之意焉。六四之於初九，六五之於九二，則所謂「鹹臨」者矣。至於上六，下無其應，猶以敦厚之德從而臨之，信乎其與之矣。初九：鹹臨，貞吉。象曰：「鹹臨貞吉」，志行正也。初九，「兌」也。以陽居剛，而在下卦之下，應乎六四。四，「坤」「艮」也，故曰「鹹臨」。「鹹」，感也。艮「兌」者，「鹹」之象也。柔上而剛下，感應以相與者也。故初九之於六四，感而後臨，是之謂「鹹臨」矣。然以九居初，六居四，陰陽專一，非所謂相與者也，故曰「貞吉」。貞者，正也。所貴乎「鹹」者，為其相與而乂吉。其貞何也？曰：四，臣位也，應乎在下之賢，可以交感而不可以相與者也。若九五、六二，則失其義矣。四之於初，感而臨之，而初九得以守其正而行其志，斯之謂「吉」矣。故子曰：「鹹臨，貞吉，志行正也。」九二：鹹臨，吉，無不利。象曰：「鹹臨，吉，無不利」，未順命也。九二，「震」也。以陽居柔而在下卦之中，應乎六五之「坤」，故曰「鹹臨」。夫「艮」、「兌」者，易之所謂「鹹」也，而此以「坤」、「震」言之，何哉？曰：「震」動而坤順也。六五、九二，柔上而剛下，感應以相與，故二之於五，亦感而後「臨」。「臨」之初與四、二與五，各得「鹹」之一體是也，謂之「鹹臨」也，故曰：「吉，無不利。」君臣之間，夫婦之際，內外相應，上下相與，不謀而同，不約而合，可謂吉矣。然而有之，所言而然，所行而善，其應如響，其行如流，使其不善而莫之違也，利於何有哉？故子曰：「鹹臨，吉，無不利，未順命也。」順者，「坤」也。「坤」在於五而不在二矣。「臨」之六爻，自三以往，其象為「坤」，在於九二，未為順矣。大臣以道事君，不可則止，以順為正者，妾婦之道也。以九居二而體乎「震」，其得大臣之義乎？六三：甘臨，無攸利。既憂之，無咎。象曰：「甘臨」，位不當也；「既憂之」，咎不長也。六三上體為「坤」，下體為「巽」，以陰居剛而在下卦之上，上無其應，而乘九二之「震」，故曰「甘臨」。「甘」，便佞也。記曰：「小人甘以壞。」四陰之「臨」二陽，猶地之臨澤也。「坤」為土，「巽」為入，以土製水而入於水，是剛浸長而壞其防也，故有「甘臨」之象。為夫剛毅忠貞者，君子之所優，而小人之所憚也。柔佞巽順者，君子之所乏，而小人之所便也。忠貞之言，逆耳苦口；巽順之說，其甘如飴。初二陽為君子，六三陰為小人。以小人柔巽，甘言媚色以入之，是以謂「甘臨」矣。方「臨」之時，君子道長，而六三之小人不知退聽，猶以邪佞之資，行巽順之道，自上而臨之，必不為君子所容，故曰：「無攸利」。三承於四，四應在初，二陽方長而當其衝，其孤危可立而待也。然「坤」為順，「巽」為伏，方「臨」之時，自知不敵，順而伏焉，庶乎其免矣。故曰：「既憂之，無咎。」夫君子之進，非小人之利也，窮而攫搏，亦其宜矣。然且匿其兇險之心，而見其順伏之意，以六三而遇九二，無閉拒之情焉，可謂知危而憂懼者矣。君子之於小人，亦豈得志而讎疾之哉？彼既憂懼而自新，惟我之為聽，則陽日以長，陰日以消，六三之小人變而為君子，則「泰」之象矣，夫又何求？故子曰：「甘臨，位不當也；既憂之，咎不長也。」一變為「泰」，夫豈長乎？六四：至臨，無咎。象曰：「至臨旡咎」，位當也。六四上體為「坤」，下體為「艮」，以陰居柔而在上卦之下，應乎初九之「兌」，故曰「至臨」。「坤」為地，「艮」為山，山高於地者也。山附於地，而臨兌澤之上，澤至而能臨之，斯之謂「至臨」矣。六四、初九，「艮」、「兌」相應，以六居四，當於其位。澤之浸長，及三而已，四其免乎？何者？入乎「巽」而止乎「艮」故也。或曰：子以山澤為「損」，明「坤」兌之為「臨」，而於此又曰「山附於地，澤至而能臨之」，何義也？曰：山澤損者，澤上即是山也。山下有澤，能無損乎？山附於地，地固自若也。澤上有地，能無臨乎？是故「損」之六三，「坤」巽乎澤，自四以往，有「艮」而無「坤」，「坤」之象毀矣。「臨」之六三，雖「巽」於澤，自四以往，「坤」象隤然，是以謂之「至臨」也。初九者，在下之賢；六四者，近君之臣也。柔上而剛下，「兌」「艮」相應，有交感之象焉。二剛浸長，至三而「泰」，六四之德，足以臨其上矣，故曰「無咎」。書曰：如有一個臣，斷斷猗無他技，其心休休焉，其如有容。人之有技，若己有之。人之彥聖，其心好之，不啻若自其口出，實能容之，以保我子孫，六四之謂矣。夫如是，何咎之有？故子曰：「至臨無咎，位當也。」六五：知臨，大君之宜，吉。象曰：「大君之宜」，行中之謂也。六五，「坤」也。以陰居剛而在上卦之中，應乎九二之「震」，故曰「知臨」也。惟天下至聖，為能聰明睿知，足以有臨也。六為柔，五為剛，居上而得中，感應以相與，得夫臨下之道矣。臨下之道，太剛則折，太柔則弛，不剛不柔，施得其當，是以謂之「知臨」也。故曰：「大君之宜，吉。」有天下而君之，謂之「大君」。「宜」，適稱也。夫所謂不剛不柔者，非但抑剛而抗柔也，有時而剛，有時而柔，當於事而合於人心，謂之「大君之宜」矣，吉孰如之？故子曰：「大君之宜，行中之謂也。」夫四、五皆「坤」象也，或言「大」，或言「至」，以其位稱之也。上六：敦臨，吉，無咎。象曰：「敦臨」之「吉」，志在內也。上六，「坤」也。以陰居柔而在上卦之上，應在六三，二爻俱陰，同體乎「坤」，無相應之義，故曰「敦臨」。「敦」，厚也，增培之義也。「坤」為厚德，以「坤」臨「坤」，是之謂「敦臨」。以「復」之「敦復」，「艮」之「敦艮」，皆取重複之義也。六三以巽順之德而臨二陽，雖不當於其位，既有憂懼之誠矣。上六又以「坤」之厚德而臨之，六三之變則為「泰」矣。三且無咎，而況於上乎？故曰：「吉，旡咎。」「包荒藏疾，不顯亦臨」，斯之謂也。故子曰：「敦臨之吉，志在內也」。嫌於六三不當其位，宜若不知不應，是以夫子發明之爾。「臨」之為大，不亦宜乎？以三之不當位，而上六其配，六四其承，皆有宜悔，是以三爻皆著「無咎」之辭。故曰：「無咎者，善補過也。」序卦曰：「物大然後可觀，故受之以親。」「觀」之成卦，臨之反也。二陽在下，四陰自上而臨之；二陽在上，四陰自下而觀之也。以坤臨「兌」謂之「臨」，以「坤」觀「震」謂之「觀」也。夫大者，小之所觀也；上者，下之所觀也。苟無臨下之大德，曷足以居於人上而為天下之所觀哉？書曰「有容德乃大」，「臨」之義也。「七世之廟，可以觀德；萬夫之長，可以觀政」，「觀」之義也。此「觀」之所以次臨。或曰：三陰為「否」，五陰為「剝」，惡其長也。四陰在「否」「剝」之間，而獨為「觀」，何哉？曰：三陰為「否」者，天地不交，外健而內順也。五陰為「剝」者，山附於地，順而止之也。四陰為觀者，風行地上，順而巽也。因其自然之象，而命以自然之名，豈強為之分別哉？「觀」，盥而不薦，有孚顒若。彖曰：大觀在上，順而巽，中正以觀天下。「觀，盥而不薦，有孚顒若」，下觀而化也。觀天之神道，而四時不忒。聖人以神道設教，而天下服矣。上巽下坤，成卦曰「觀」者，初為「坤」，二亦為「坤」，三為「艮」，四為「巽」。「順以巽」，則化行而民服矣。何以明其為「觀」哉？謂其有「艮」象焉。「坤」為眾，「艮」為「止」，「巽」為齊。眾止而齊，斯以為「觀」而已矣。「觀，盥而不薦，有孚顒若。」何謂也？曰：可觀者，二陽也，觀之者，四陰也。九五為「盥」，而上九為薦也。自下觀上，近則睹之。故九五中正，為天下之所觀。六四最近，為觀光之上賓。四陰之所觀者，九五而已。至於上九，隔乎九五，觀瞻之所不及也。故曰：「觀，盥而不薦也。」未有盥而不薦者也，未有觀，盥而不觀薦者也。然而沃盥在於阼階，薦獻在於室寢。阼階之下可得而觀，室寢之中非眾之所睹也。故曰：「觀，盥而不薦也。」化民之道，莫遠於誠。行誠之道，莫重於祭。祭祀之禮，莫先於盥。盥，洗手也，奠幣酌鬯，以求神之初也。宗廟致敬，精誠專一，莫盛於此時。及夫既灌之後，三獻而薦腥，五獻而薦熟，其文繁，其禮縟，雖強有力者，猶有時而惰矣。則其精誠之著見，豈能如沃盥之時耶？故子曰：「禘自既灌而往者，吾不欲觀之矣。」謂其精誠之不一也。孚之言信也，顒之言嚴也。方盥之初，誠意充乎內，肅敬形於外，盛德之容，觀者自化，不言而信，不戒而嚴，誠孝所格，無乎不通，故有孚於下，顒顒如也。微之顯，誠之不可揜也如此夫！孟子曰：「至誠而不動者，未之有也；不誠，未有能動者也。」夫誠者，自成也，萬物之所成終而所成始也，未有誠於盥而不誠於薦者也。然而彖以是為言者，蓋曰民之化我，觀我之盥而不觀於薦也。若觀於薦，則化我未必若是之孚也，是以「觀，盥而不薦」也。夫「觀，盥而不觀薦」者，以吾之誠敬在於盥也。吾之所以致吾誠敬者，豈其盥之時耶？固在於齋之日也。散齋七日，致齋三日，虛而明，一而精，人莫之見也。始發於盥，其容肅然，故可觀也。嗚呼！古之聖人所以齋戒以神明其德者，其取諸此乎！故子曰：「大觀在上，順而巽，中正以觀天下。」「觀，盥而不薦，有孚顒若」，下觀而化也。觀人者謂之觀，觀於人者謂之觀。觀，官喚反。大而在上者，二陽也。中正以觀者，其惟五乎？是以觀，盥而不薦者也。中正既釋其義，又從而申明之曰：「觀天之神道，而四時不忒，聖人以神道設教，而天下服矣。」何謂也？曰：天者，人之所觀也；君者，民之所觀也。是以聖人觀於天，而天下觀於聖人也。天何言哉？四時行焉，百物生焉。天，神道也。聖人體天，故亦以神道設教，修己以安百姓，篤恭而天下平，蓋有不言而信者矣。神者，何也？一之謂也。一者何也？誠之謂也。故曰：至誠如神。誠者，天之道也。誠則形，形則著，著則明，明則動，動則變，變則化，唯天下之至誠為能化，謂之神道，不亦宜乎？子曰：知變化之道，其知神之所為乎？徒見四時之行、萬物之育、黎民之變、蠻貊之孚，而不知其所以致此者天，故是謂之神也。然則宗廟致敬，不出堂廡之間，而化行於天下，豈不信哉！或問禘之說，子曰：「不知也。知其說者之於天下也，其如示諸掌乎？」此之謂也。卦名及諸爻並如字讀，唯「大觀在上，中正以觀天下」。九五「觀民」之「觀」，當以去聲讀之。象曰：風行地上，「觀」。先王以省方觀民設教。「風」者，「巽」也，「地」為「坤」也。風行地上，無所不徧，故先王以之巡守省方，觀民俗之好惡，而為之設教焉，猶風之行於地上也。然「觀」之成卦，以四陰而觀二陽，取下觀而化之義。孔子於彖辭言「以神道設教」，於九五之爻辭言「觀我生，觀民也」，與大象所謂「觀民設教」，辭同而義異矣。雜卦曰：「臨觀之義，或與或求。」「與求」之義，已解在「臨」。「臨」為與，則「觀」為求。以人之求我，而非我之求人也。是以「觀」之諸爻，二陽者，人之所求也；四陰者，求人者也。初為「童觀」，二為「𬮭觀」，三為「進退」，四為「觀光」者，求人者也。五為「盥」，上為「薦」者，人之所求也。為禮不敬，吾何以觀之哉！初六，童觀，小人無咎，君子吝。象曰：「初六童觀」，小人道也。初六，「坤」也，以陰居剛，而在下卦之下，上無其應，而遠於九五，承於六二，二亦「坤」也，故曰「童觀」。「坤」為眾，在下為小者，童子之象。子貢曰：「不得其門而入，不見宗廟之美。」若童子之觀，最在人後，雖得其門而入，亦不能有所見；雖使見之，亦不能知其意義也。故曰：「小人無咎，君子吝。」下民至愚，隨上所化，由之而不知，何咎之有？若君子者，行而不著，習而不察，旅進而觀，了無所睹，雖當堯、舜、文、武之時，而不明禮樂教化之意，含哺鼓腹，不知帝力，於我何有？名為君子，不亦可羞哉！故子曰：「初六童觀，小人道也。」六二，𬮭觀，利女貞。象曰：「𬮭觀女貞」，亦可醜也。六二，「坤」也，以陰居柔而在下卦之中，應乎九五之震，故曰「𬮭觀」。震為明，「坤」為闔戶，闔戶而觀，𬮭於戶牖者也。自下觀上，近則睹之。二雖與五為配，有觀感之義，然去之遠矣。體陰而居柔，處內而守中，在上而居貞，是以謂之「𬮭觀」也。故曰「利女貞」。幽閨靜僻者，女子之正也。在禮，送迎不出門，見兄弟不逾閾。雖有觀禮之心，而不失自防之正，斯為利矣。君子正其衣冠，尊其瞻視，𬮭牖而觀，不亦醜乎？當觀之時，聖人在上，天朝中天，萬物鹹觀。況於六二是其正應，所宜脫身邱園，觀光上國，而乃自埋於民，自藏於野，雖被容光之照，𬮭見教化之一二，自以為得之矣。譬如坐井觀天，所得幾乎？故君子以為可醜也。伊尹耕於有莘之野，而樂堯舜之道，及其幡然而起曰：「我豈若使是君為堯舜之君哉？豈若使是民為堯舜之民哉？豈若吾身親見之哉？」故子曰：「𬮭觀女貞，亦可醜也。」六三：觀我生，進退。象曰：「觀我生，進退」，未失道也。六三下體為「坤」，上體為「艮」，以陰居剛而在下卦之上，應乎上九之「兌」，故曰「觀我生」。「生」，猶動也；「我」，自謂也。在卦六爻皆以宗廟行禮為義。初六「童子」之觀，六二「婦女」之𬮭也；六三奉豆執籩之聯，六四在位陪祠之列也；九五沃盥之始，上九薦獻之時也。六三應於上九，執事以承薦者也，是以自觀其動也，故曰「進退」。三、四者，內外之交，上下之際，進退之地也。以六居三，「進退」之象也。宗廟之事，群臣百工駿奔走，執豆籩，或進而承君，或退而復位，非若陪祠之列屹立而不動也。「震」為動，「巽」為進退，而「坤」、「艮」稱之，何哉？為其近於「震」而承於「巽」，隨其盥薦以為進退也。然則四之不為進退，何也？曰：四以進乎上，卦得其位，以近天子之光，又何進退之云乎？聖人在上，固所宜仕，若不自觀其動，進退以禮，去就以義，而惟位之為急，至於鑽穴逾垣而從之者，失其道矣。故子曰：「觀我生，進退，未失道也。」六四：觀國之光，利用賓於王。象曰：「觀國之光」，尚賓也。六四下體為「坤」，上體為「巽」，以陰居柔而在上卦之下，承乎九五之「震」，故曰：「觀國之光。」「震」為旦，有光明之象焉。夫國莫重於禮，禮莫重於祭。宗廟之事，陳其籩豆，列其鼎俎，設其鼓鍾，舞其幹翟，薦其馨香，昭其度數，文物以紀之，聲明以發之，有國之光華也。四得其位，以承於五，能順而「巽」，斯得而觀之矣，故曰：「利用賓於王。」五為「震」，四為「巽」。「震」、「巽」配也。五居天位，有王之象。以四承五，以「巽」配「震」，有賓主之象焉。周官大行人「以九儀辨諸侯之命，等諸臣之爵，以同邦國之禮，而大其賓客。」書曰：「賓於四門，四門穆穆。虞賓在位，群后德讓。」至於夷蠻戎狄，猶有來賓之義，非特二王之後也，三代之王，得萬國之歡心，四海之內各以其職來助，鹹造在庭，以觀上國之光，斯為利矣。天下文明，光被四表，賢德之人仕於王朝，人君賓禮，不敢盡臣之。夫豈特人臣之利，天下國家之利也。故子曰：「觀國之光，尚賓也。」「尚」者，上也。「觀國之光」，惟尚賓為近之矣。詩云：「振鷺于飛，於彼西雝；我客戾止，亦有斯容。」觀光之「尚」，賓也。九五：觀我生，君子無咎。象曰：「觀我生」，觀民也。九五，「震」也。以陽居剛而居上卦之中，彖所謂「中正以觀天下」者也，故曰「觀我生」。「生」，猶動也；我，自謂也。「震」為旦，為動，質明而行事，是故九五「盥」之時也。方盥之時，精神專一，致愛則存，致愨則著，以其恍惚以與神明交，洞洞乎，屬屬乎，如弗勝，如將失之，是以耳無所聞，目無所睹，惟自觀其動而已矣。自觀其動，在我無失，孝敬之心，誠愨之意，見於其面，盎於其背，儼然可觀，觀者不言化之矣，故曰：「君子無咎。」非盛德之君子，其能無咎乎？君者，民之表也，表正而影正矣。故子曰：「觀我生，觀民也。」「觀民」之義，與大象不同，說者皆於此失之。當讀為「大觀」，「觀天下」之「觀」。「觀」，示也。為人上者，言思可道，行思可樂，德義可尊，作事可法，容止可觀，進退可度，以臨其民，是以其民畏而愛之，則而象之。聖人之以神道設教，其斯而已矣。五下應二，二為「坤」，自四以下，其象皆「坤」，「坤」為民，故有「觀民」之象也。上九，觀其生，君子無咎。象曰：「觀其生」，志未平也。上九，「兌」也。以陽居柔，而在上卦之上，應乎六三之艮，故曰「觀其生」。生猶動也，其謂三也。下艮上兌，有相與之意焉。上九隔乎九五，不為民之所觀，而反觀於六三者也。何者？觀之六爻，惟三五有艮、震之體。上九雖陽，而其體兌也。以兌從艮，斯反觀之矣。兌，說也。孝子之享親，其薦之也，必有愉色婉容，是以繋之兌也。震為卯，兌為酉，質明而行事，曰晏而禮成，是故上九薦之時也。方薦之時，禮文繁縟，羞其俎豆，序其禮樂，備其百官，奉承而進之。或進乎下，或進乎上，以相與成禮者也。詩云：「濟濟闢王，左右趨之。」書雲：「駿奔走，執豆籩。」於斯時也，雖欲自觀其動，不可得矣。是故觀我生者，目注乎躬也。觀其生者，目注乎物也。目注乎物，隨物而動。其進之也，敬以愉，其薦之也，敬以欲。已徹而退，敬齋之色，不絕於面，如是其難也。故曰：「君子無咎。」非盛德之君子，其能無咎乎？詩云：「有來雝雝，至止肅肅。相維闢公，天子穆穆。」觀我生也。「濟濟多士，秉文之德。於薦廣牡，相予肆祀。」觀其生也。故子曰：「觀其生，志未平也。」事物之來，紛乎吾前，欲其心平志一於盥之時，亦已難矣。或曰：「大觀在上，下觀而化，若斯之盛也。不繫之吉，而但言無咎，何哉？」曰：是固然矣。觀我生者，以我一身動為天下萬民之所觀。過言則民作辭，過動則民作則。有諸內必形諸外，誠於此必動於彼，故莫見乎隱，莫顯乎微。由是言之，觀我生者，缺精缺欲其無咎，不亦難乎？觀其生者，缺目觀天下萬物之動，民之好惡，必缺良窳，必知其故，左右前後，罔匪正缺罔有不臧，無遠不燭，無幽不見。由缺觀其生者，觀之至詳也，欲其無咎，不亦宜乎？至精者，正心誠意之謂也；至詳者，應變酬酢之謂也。當此之時，而免於咎者，吉之大者也。非明明德之君子，其能無咎乎？嗚呼！非天下之至精，不足以觀天下之至詳也；非天下之至靜，不足以觀天下之至動也；非天下之至一，不足以觀天下之至眾也。是故取乎盥，而不取乎薦也。觀之時義大矣哉！周易經傳集解卷十",-1)])])}const f=t(r,[["render",c]]);export{_ as __pageData,f as default};
